UPDATE albums SET song_count=(SELECT COUNT(*) FROM song_masters WHERE song_masters.album_id=albums.id),size=(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id=albums.id),updated_at=unixepoch() WHERE id IN ('pending-uploads','al-cd703f7e5c09e82d79eee0fcab49c3aa');
INSERT INTO work_queue (id,task_type,payload,status,created_at) SELECT 'pending-backfill-guard','metadata','{}','guard_failed',unixepoch() WHERE changes()!=2 OR (SELECT COUNT(*) FROM song_masters WHERE album_id='al-cd703f7e5c09e82d79eee0fcab49c3aa')!=12 OR (SELECT song_count FROM albums WHERE id='al-cd703f7e5c09e82d79eee0fcab49c3aa')!=12 OR (SELECT size FROM albums WHERE id='al-cd703f7e5c09e82d79eee0fcab49c3aa')!=(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-cd703f7e5c09e82d79eee0fcab49c3aa');
